```javascript
function switchAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  // Find the index of the second adjective (the one before the noun)
  let secondAdjectiveIndex = -1;
  for (let I = 0; I < words.length; i++) {
    const word = words[i].trim();
    if (word.endsWith("ly") || /\d{3}$/.test(word)) {
      // Ignore adverbs and numbers at the end of words
      continue;
    }
    if (secondAdjectiveIndex === -1 && !words[i - 1].endsWith("ly")) {
      // Found the first adjective
      secondAdjectiveIndex = i;
    } else if (!words[i - 1].endsWith("ly") && !words[i - 2].endsWith("ly")) {
      // Found the second adjective
      break;
    }
  }

  // If we couldn't find two adjectives, don't switch them
  if (secondAdjectiveIndex === -1) {
    return sentence;
  }

  // Swap the positions of the first and second adjectives
  const [firstAdjective, ...rest] = words.slice(0, secondAdjectiveIndex);
  const [secondAdjective, ...middle] = words.slice(secondAdjectiveIndex, words.length);
  const reversedMiddle = middle.reverse();
  const result = [...reversedMiddle, firstAdjective, ...middle, secondAdjective, ...rest];
  return result.join(" ");
}

