  // Perform the swap using a replacement callback
  let result = words.slice(0, regex.lastIndex).join(" ");
  let match = null;
  while ((match = regex.exec(words.slice(regex.lastIndex).join(" "))) !== null) {
    const [_, before1, after1, before2, after2, after3] = match;
    result += after3 + after2 + before2 + before1 + after1;
  }
  result += words.slice(regex.lastIndex).join(" ");

  // Return the modified string
  return result;
}

