let homophones = ["is": "are", "is": "it's", "is": "its", "owe": "ow", "weigh": "way"]

enum CorrectionError: Error {
    case unknownHomophone(String)
}

func replaceHomophones(_ text: String) throws -> String {
    var result = ""
    for (oldWord, newWord) in homophones {
        let oldSubstrings = text.components(separatedBy: oldWord)
        for I in 0..<oldSubstrings.count - 1 {
            let first = oldSubstrings[i]
            let last = oldSubstrings[i+1]
            let middle = newWord
            result += "\(first)\(middle)\(last)"
        }
        guard let last = oldSubstrings.last else {
            throw CorrectionError.unknownHomophone(oldWord)
        }
        result += last
    }
    return result
}

