let homophones: [String: String] = [
    "there": "their",
    "they're": "they are",
    "too": ["to", "two"] // "too" has multiple meanings
]

// Prompt user for input passage
print("Enter the passage (press enter after each line):")
var inputPassage = ""
while let line = readLine() {
    inputPassage += line + " "
}
inputPassage.removeLast() // Remove trailing space

// Correct homophones in passage
var outputPassage = ""
for word in inputPassage.components(separatedBy: .whitespaces) {
    for (key, value) in homophones {
        if let range = word.range(of: key), !word.prefix(upTo: range.lowerBound).hasSuffix("'"), value.count == range.upperBound - range.lowerBound {
            outputPassage.append(contentsOf: String(word[..<range.lowerBound]) + String(value[range.upperBound - range.lowerBound ..< value.endIndex]) + String(word[range.upperBound..<word.endIndex]))
            break // Stop checking other homophones for this word
        }
    }
    outputPassage.append(word)
}
outputPassage.removeLast() // Remove trailing space

// Output corrected passage
print("Corrected passage:\n\(outputPassage)")
```

