```cpp
#include <iostream>
#include <cstdlib>
#include <cstring>
#include <nlohmann/json.hpp>

constexpr int MAX_SIZE = 100;

void bubbleSort(int arr[], int n) {
    bool swapped = true;
    for (int i = 0; I < n - 1 && swapped; ++i) {
        swapped = false;
        for (int j = 0; j < n - I - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                std::swap(arr[j], arr[j + 1]);
                swapped = true;
            }
        }
    }
}

