response:
To implement bubble sort in C++ for sorting an integer array, we can follow these steps:

1. Define a function to perform bubble sort. This function will take the array and its size as arguments.

2. Inside the bubbleSort() function, iterate through the array using two nested loops - one for keeping track of the current position and another for comparing adjacent elements.

3. Swap the adjacent elements if they are in the wrong order.

4. Continue iterating until no swaps are made during a pass.

Here's the implementation:

```cpp
void bubbleSort(int arr[], int n) {
    bool swapped = true; // flag to check for any swap during a pass
    for (int i = 0; i < n-1 && swapped; i++) { // outer loop runs n-1 times
        swapped = false; // assume no swap
        for (int j = 0; j < n-i-1; j++) { // inner loop runs n-i times
            if (arr[j] > arr[j+1]) { // compare adjacent elements
                int temp = arr[j]; // swap them
                arr[j] = arr[j+1];
                arr[j+1] = temp;
                swapped = true; // set flag to true if swap is made
            }
        }
    }
}

int main() {
    int arr[] = {5, 2, 9, 1, 5, 6};
    int n = sizeof(arr)/sizeof(arr[0]);

    bubbleSort(arr, n);

    // Print sorted array
    for (int i=0; i<n; ++i) {
        cout << arr[i] << " ";
    }

    return 0;
}
```

