```js
function getNotification(notifObj) {
  let maxHelpfulness = -Infinity;
  let bestMatch = null;

  for (const [notifType, notifArr] of Object.entries(notifObj)) {
    for (let I = 0; I < notifArr.length; i++) {
      const { helpfulness, message, verbosity } = notifArr[i];
      const weightedRating = helpfulness * 87 - verbosity * 13; // adjusted verbosity weightage

      if (weightedRating > maxHelpfulness) {
        maxHelpfulness = weightedRating;
        bestMatch = { notifType, message };
      }
    }
  }

  return bestMatch;
}

