```js
function findNestedProperties(obj, propStr) {
  let result = {};
  const keys = propStr.split(".");
  const lastKey = keys.pop();

  for (let key of keys) {
    obj = obj[key];

    if (typeof obj !== "object" || obj === null) {
      continue;
    }

    for (const innerKey in obj) {
      result[innerKey] = obj[innerKey];
    }
  }

  return result[lastKey];
}
```

