```js
const words = ['skyscraper', 'chair', 'umbrella', 'curtain'];
const lengths = words.map(word => word.length);

const sortedWords = words.sort((a, b) => {
  const aLength = lengths[words.indexOf(a)];
  const bLength = lengths[words.indexOf(b)];
  if (aLength === bLength) {
    // If both words have the same length, sort alphabetically
    return a.localeCompare(b);
  } else {
    // Otherwise, sort by length first
    return bLength - aLength;
  }
});

