  let count = 0; // keeps track of number of replacements made
  let pos = 0; // starting position for indexOf() method
  while (true) {
    const index = input.indexOf(oldWord, pos);
    if (index === -1) break; // end of string reached

    // Check if oldWord is part of a larger word
    const prevChar = input[index-1];
    const nextChar = input[index+oldWord.length];
    if (prevChar !== ' ' || nextChar !== ' ') {
