check_numeric <- function(x) {
  # Check for missing values (NA)
  x[is.na(x)] <- 0 # Replace NA with 0

  # Try converting to numeric and check if all elements are numeric
  tryCatch(
    {
      as.numeric(x)

      # All elements were successfully converted
