```typescript
import { Injectable, NestMiddleware } from '@nestjs/common';
import { ExecutionContext, HttpStatus } from '@nestjs/core';
import { Observable } from 'rxjs';

@Injectable()
export class EnvGuard implements NestMiddleware {
  use(context: ExecutionContext): Observable<void> | Promise<void> | void {
    const req = context.switchToHttp().getRequest();
    const isDev = req.env === 'development';

    if (isDev) {
      return super.use.call(this, context); // Call next middleware
    } else {
      return new Observable(() => {}); // Return empty observable to stop execution
    }
  }
}

// Usage:
// Decorate your controller method with EnvGuard decorator
// @EnvGuard()
// getAllUsers(): User[] { ... }
```

This decorator checks the `NODE_ENV` value in the request environment variables. If it's set to "development", it passes control to the next middleware using the `super.use.call(this, context)`. Otherwise, it returns an empty observable to prevent further execution.

The helper function `super.use.call(this, context)` is used to invoke the original `use()` method on the parent class `NestMiddleware`, which actually calls the next middleware. This allows us to avoid duplicate code and keep our implementation DRY.

