    weight += item.reduce((arrWeight, subItem) => arrWeight + calculateWeight(subItem), 0);
  } else if (item !== '') {
    weight += 50;
  }
  return weight;
}

console.log(`Weighted rating: ${weightedDiff}`);
```

The output of this script will be the weighted rating calculated based on the provided Jest diff. The `calculateWeight()` function is used to recursively calculate the weight of nested arrays and objects

