     const { isOpen, selectedItem, getMenuProps, getComboboxProps, getInputProps, getItemsProps } = useCombobox({
       items: searchResults,
       getItemPredicate: (item: SearchResult) => item.email.toLowerCase().startsWith(selectedItem?.email?.toLowerCase() || ''),
       highlightedIndex: searchResults.findIndex((result) => result.email === selectedItem?.email),
     });

     return (
       <div className="email-autocomplete">
         <input type="text" {...getInputProps()} />
         <ul {...getMenuProps()}>
           {isOpen && searchResults.map((result, index) => (
             <li key={result.id} {...getItemsProps({ index })}>
               <span>{result.email}</span>
             </li>
           ))}
         </ul>
         <input type="hidden" value={selectedItem ? selectedItem.email : ''} {...getComboboxProps()} />
       </div>
     );
   };

