```swift
func rearrangePhrase(_ phrase: String) -> String {
    let sortedLetters = phrase.filter { !$0.isWhitespace }.sorted()
    let newPhrase = String(sortedLetters)

    let positiveWords = ["blessings", "happiness", "joy", "gratitude", "love"]
    var outputString = ""

    if let indexOfFirstNonWhitespaceChar = phrase.firstIndex(where: { !$0.isWhitespace }) {
        let firstLetter = String(phrase[indexOfFirstNonWhitespaceChar])
        let restOfPhrase = String(phrase.dropFirst(indexOfFirstNonWhitespaceChar)))

        let sortedRestOfPhrase = restOfPhrase.filter { !$0.isWhitespace }.sorted()
        let sortedPositiveWords = positiveWords.shuffled()
        let shuffledNewPhrase = String(sortedLetters.shuffled())

        for (i, letter) in shuffledNewPhrase.enumerated() {
            let spaceCount = i % 4 == 0 ? 2 : 1
            outputString += String(repeatElement: " ", count: spaceCount)
            outputString += String(letter)

            if sortedLetters[i] == "e" || sortedLetters[i] == "E" {
                outputString += "x"
            }

            if i < sortedRestOfPhrase.count {
                outputString += String(sortedRestOfPhrase[i])
            } else {
                outputString += String(sortedPositiveWords[i % sortedPositiveWords.count])
            }
        }
    }

    return "Life is worth living with \(outputString)!"
}
```

