const storage = multer.diskStorage({
  destination: function (req, file, cb) {
    cb(null, 'tmp/')
  },
});
const upload = multer({ storage: storage });

// Rota para carregar a imagem
app.post('/upload', upload.single('image'), async (req, res) => {
  // Convertendo a imagem para binário
  const imageData = fs.readFileSync(req.file.path);
  const contentType = mime.getType(req.file.originalname);

  // Inserindo a imagem no MongoDB
  await db.collection('images').insertOne({
    _id: new ObjectID(),
    name: req.file.originalname,
    contentType: contentType,
    data: imageData,
  });

  // Retornando o caminho da imagem carregada
  return res.send(`http://localhost:3000/images/${req.file.filename}`);
});
```

