string rearrangeLetters(const string& letters) {
    int consonantCount = 0, vowelCount = 0;
    string result;
    for (char c : letters) {
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            vowelCount++;
        } else {
            consonantCount++;
        }
        result.push_back(c);
