    // Compare two elements and return negative/zero/positive value based on their order
    return a - b;
  });
}

// Example usage
const inputArray = [3, 7, 2, 1, 6];
const sortedArray = sortArray(inputArray);
console.log(sortedArray); // Output: [1, 2, 3, 6, 7]
```

The `sort()` method is called on the array passed as argument to the `sortArray()` function. The callback function takes two arguments (`a` and `b`) representing the current pair of elements being compared during the sorting process. In this case, we simply subtract `a` from `b` to determine their relative order. If `a` is less than `b`, it returns a negative number, indicating that `a` should come before `b` in the sorted array. If `a` is greater than or equal to `b`, it returns zero or a positive number, respectively, depending on whether `a` should be placed after or between `b` and any other element being compared at the same time.

